-- 세트 531. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set531.sql, 05·06·08. docs/specs/spec_pilot_gap_sets.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 531, '도커 문제 해결 상황집: compose 가 안 올라올 때', 'docker compose up 이 실패하거나, 올라왔는데 기대대로 동작하지 않는 상황을 재현된 환경에서 고칩니다. YAML 들여쓰기 오류, 필수 변수 누락(${VAR:?}·.env), 조용히 빈 값이 되는 변수 오타, 호스트 포트 중복, 컨테이너 이름 충돌, depends_on 만으로는 준비를 보장하지 않는 문제(healthcheck + condition), 고아 컨테이너(--remove-orphans)를 오류 메시지 → 원인 → 고치기 순서로 해결하고 docker compose config 로 점검합니다.', 'docker', '도커'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 531);
UPDATE quest_set SET display_order = 752, unit_id = (SELECT id FROM unit WHERE id = 26), icon = '🧩' WHERE id = 531;

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 531, 1, 'YAML 들여쓰기 오류: 파일을 읽지 못한다', '`/tmp/work/q1` 의 `compose.yaml` 로 `docker compose config -q` 를 하면 `did not find expected key` 같은 **YAML 문법 오류**가 나고 줄·칸 번호가 함께 표시됩니다. (`config -q` 는 파일을 읽어 검증만 하고 조용히 끝납니다.) 오류 위치를 보고 파일을 고쳐 검증이 통과하게 한 뒤, `docker compose config --services` 의 결과(서비스 이름 목록)를 `/tmp/q1.txt` 에 저장하세요. 서비스 `web` 과 `cache` 는 둘 다 남아 있어야 합니다.', '오류에 나온 줄 번호 근처를 `cat -A` 나 `sed -n` 으로 확인해 보세요. YAML 에서 같은 단계의 키는 **같은 칸 수**로 시작해야 합니다. 이 문제를 풀 때는 `/tmp/work/q1` 폴더 안에서 명령을 실행하세요.', 'cd /tmp/work/q1
docker compose config -q
sed -i ''s/^   ports:/    ports:/'' compose.yaml
docker compose config -q && docker compose config --services > /tmp/q1.txt
cat /tmp/q1.txt

# ports 의 들여쓰기가 3칸이라 image 와 단계가 어긋났다. 같은 단계의 키는 같은 칸 수(여기서는 4칸)로 맞춘다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; rm -rf /tmp/work /tmp/q*.txt; mkdir -p /tmp/work/q1; cat > /tmp/work/q1/compose.yaml <<''EOF''\\nservices:\\n  web:\\n    image: nginx:alpine\\n   ports:\\n      - \\"8080:80\\"\\n  cache:\\n    image: alpine\\n    command: sleep 3600\\nEOF\\n"]', '["sh", "-c", "( cd /tmp/work/q1 && docker compose config -q ) && ( cd /tmp/work/q1 && docker compose config --services | sort | tr \\"\\\\n\\" \\" \\" | grep -qx \\"cache web \\" ) && ( grep -qx web /tmp/q1.txt && grep -qx cache /tmp/q1.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "compose.yaml 검증이 통과한다", "cmd": ["sh", "-c", "cd /tmp/work/q1 && docker compose config -q"]}, {"label": "web 과 cache 서비스가 모두 있다", "cmd": ["sh", "-c", "cd /tmp/work/q1 && docker compose config --services | sort | tr \\"\\\\n\\" \\" \\" | grep -qx \\"cache web \\""]}, {"label": "서비스 목록을 저장했다", "cmd": ["sh", "-c", "grep -qx web /tmp/q1.txt && grep -qx cache /tmp/q1.txt"]}]', '[{"title": "Compose 파일 보간(interpolation)", "url": "https://docs.docker.com/reference/compose-file/interpolation/"}, {"title": "depends_on", "url": "https://docs.docker.com/reference/compose-file/services/#depends_on"}, {"title": "docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 531 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 531, 2, 'required variable is missing: 필수 변수가 비어 있다', '`/tmp/work/q2` 에서 `docker compose up -d` 를 하면 `required variable APP_IMAGE is missing a value` 오류가 나며 **아무것도 시작되지 않습니다**. `compose.yaml` 의 `image: ${APP_IMAGE:?APP_IMAGE 를 정하세요}` 는 변수가 없거나 비어 있으면 일부러 멈추는 **필수 변수** 표시입니다. `compose.yaml` 은 **고치지 말고**, 같은 폴더의 `.env` 파일(`변수=값` 한 줄씩)로 `APP_IMAGE` 를 `nginx:alpine` 으로 정한 뒤 서비스를 올려 실행 중이게 만드세요.', 'compose 는 실행한 폴더의 `.env` 파일을 자동으로 읽어 `${변수}` 를 채웁니다. 파일 이름 앞의 점과 폴더 위치를 확인하세요. 변수 이름은 대소문자까지 정확히 맞아야 합니다.', 'cd /tmp/work/q2
echo ''APP_IMAGE=nginx:alpine'' > .env
docker compose up -d
docker compose ps

# ${VAR:?메시지} 는 변수가 없거나 빈 값이면 오류로 멈춘다. 값은 환경 변수 또는 같은 폴더의 .env 로 준다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; rm -rf /tmp/work /tmp/q*.txt; mkdir -p /tmp/work/q2; cat > /tmp/work/q2/compose.yaml <<''EOF''\\nservices:\\n  web:\\n    image: ${APP_IMAGE:?APP_IMAGE 를 정하세요}\\nEOF\\n"]', '["sh", "-c", "( grep -q ''^APP_IMAGE='' /tmp/work/q2/.env && (cd /tmp/work/q2 && docker compose config | grep -q ''image: .\\\\?nginx:alpine'') ) && ( grep -q \\"APP_IMAGE:?\\" /tmp/work/q2/compose.yaml ) && ( cd /tmp/work/q2 && [ \\"$(docker compose ps --status running -q web | wc -l)\\" = 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": ".env 로 APP_IMAGE 가 nginx:alpine 으로 풀린다", "cmd": ["sh", "-c", "grep -q ''^APP_IMAGE='' /tmp/work/q2/.env && (cd /tmp/work/q2 && docker compose config | grep -q ''image: .\\\\?nginx:alpine'')"]}, {"label": "compose.yaml 의 필수 변수 표시는 그대로다", "cmd": ["sh", "-c", "grep -q \\"APP_IMAGE:?\\" /tmp/work/q2/compose.yaml"]}, {"label": "web 이 실행 중이다", "cmd": ["sh", "-c", "cd /tmp/work/q2 && [ \\"$(docker compose ps --status running -q web | wc -l)\\" = 1 ]"]}]', '[{"title": "Compose 파일 보간(interpolation)", "url": "https://docs.docker.com/reference/compose-file/interpolation/"}, {"title": "depends_on", "url": "https://docs.docker.com/reference/compose-file/services/#depends_on"}, {"title": "docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 531 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 531, 3, '변수가 조용히 빈 값이 된다: docker compose config 로 점검', '`/tmp/work/q3` 에서 `docker compose up -d` 를 하면 `invalid reference format` 오류가 납니다. 이번에는 `image: nginx:${TAG}` 처럼 `:?` 없이 변수를 썼고, 변수가 없으면 **경고만 내고 빈 문자열**로 처리합니다. 먼저 `docker compose config | grep image` 로 **실제로 풀린 이미지 이름**을 확인하고, 그 결과(고치기 전)를 `/tmp/q3_before.txt` 에 저장하세요. 그다음 원인을 고쳐 `docker compose config | grep image` 가 `nginx:1.27-alpine` 을 보이게 하고, 그 결과를 `/tmp/q3.txt` 에 저장하세요.', '`config` 는 변수를 모두 풀어서 보여 줍니다. 이미지 이름 끝이 비어 있다면 `.env` 의 **변수 이름**을 compose.yaml 에 적힌 것과 글자 단위로 비교해 보세요.', 'cd /tmp/work/q3
docker compose config | grep image > /tmp/q3_before.txt
cat /tmp/q3_before.txt
sed -i ''s/^TAGS=/TAG=/'' .env
docker compose config | grep image > /tmp/q3.txt
cat /tmp/q3.txt

# .env 에 TAGS 로 잘못 적어 TAG 가 비었다. config 로 풀린 결과를 보면 nginx: 로 끝나 원인이 보인다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; rm -rf /tmp/work /tmp/q*.txt; mkdir -p /tmp/work/q3; cat > /tmp/work/q3/compose.yaml <<''EOF''\\nservices:\\n  web:\\n    image: nginx:${TAG}\\nEOF\\necho ''TAGS=1.27-alpine'' > /tmp/work/q3/.env; "]', '["sh", "-c", "( grep -q ''image: .*nginx:.\\\\?$'' /tmp/q3_before.txt ) && ( cd /tmp/work/q3 && docker compose config 2>/dev/null | grep -q ''image: nginx:1.27-alpine'' ) && ( grep -q ''nginx:1.27-alpine'' /tmp/q3.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "고치기 전 결과(빈 태그)를 저장했다", "cmd": ["sh", "-c", "grep -q ''image: .*nginx:.\\\\?$'' /tmp/q3_before.txt"]}, {"label": "고친 뒤 이미지가 nginx:1.27-alpine 이다", "cmd": ["sh", "-c", "cd /tmp/work/q3 && docker compose config 2>/dev/null | grep -q ''image: nginx:1.27-alpine''"]}, {"label": "고친 결과를 저장했다", "cmd": ["sh", "-c", "grep -q ''nginx:1.27-alpine'' /tmp/q3.txt"]}]', '[{"title": "Compose 파일 보간(interpolation)", "url": "https://docs.docker.com/reference/compose-file/interpolation/"}, {"title": "depends_on", "url": "https://docs.docker.com/reference/compose-file/services/#depends_on"}, {"title": "docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 531 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 531, 4, 'port is already allocated: 호스트 포트가 겹친다', '`/tmp/work/q4` 에서 `docker compose up -d` 를 하면 `Bind for 0.0.0.0:8080 failed: port is already allocated` 로 실패합니다. 호스트의 8080 번 포트를 이미 `blocker` 컨테이너가 쓰고 있고, 그 컨테이너는 **다른 서비스가 쓰는 중이라 건드리면 안 됩니다**. `blocker` 는 그대로 두고 `compose.yaml` 의 **호스트 쪽 포트**만 바꿔 `web` 을 실행 중으로 만드세요.', '`ports` 는 `호스트:컨테이너` 순서입니다. 어느 쪽 숫자가 호스트 포트인지 확인하고, 그쪽만 비어 있는 다른 번호로 바꾸세요. 누가 8080 을 쓰는지는 `docker ps` 에서 확인할 수 있습니다.', 'cd /tmp/work/q4
docker ps --format ''{{.Names}} {{.Ports}}''
sed -i ''s/"8080:80"/"8081:80"/'' compose.yaml
docker compose up -d
docker compose ps

# 호스트 포트는 한 번에 한 프로세스만 쓴다. 컨테이너 쪽 포트(80)는 그대로 두고 호스트 쪽만 바꾼다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; rm -rf /tmp/work /tmp/q*.txt; mkdir -p /tmp/work/q4; cat > /tmp/work/q4/compose.yaml <<''EOF''\\nservices:\\n  web:\\n    image: nginx:alpine\\n    ports:\\n      - \\"8080:80\\"\\nEOF\\ndocker run -d --name blocker -p 8080:80 nginx:alpine >/dev/null; sleep 1; "]', '["sh", "-c", "( [ \\"$(docker inspect -f {{.State.Running}} blocker 2>/dev/null)\\" = true ] ) && ( cd /tmp/work/q4 && [ \\"$(docker compose ps --status running -q web | wc -l)\\" = 1 ] ) && ( cd /tmp/work/q4 && P=$(docker port $(docker compose ps -q web) 80/tcp | head -1 | sed \\"s/.*://\\") && [ -n \\"$P\\" ] && [ \\"$P\\" != 8080 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "blocker 는 그대로 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f {{.State.Running}} blocker 2>/dev/null)\\" = true ]"]}, {"label": "web 이 실행 중이다", "cmd": ["sh", "-c", "cd /tmp/work/q4 && [ \\"$(docker compose ps --status running -q web | wc -l)\\" = 1 ]"]}, {"label": "web 의 호스트 포트가 8080 이 아니다", "cmd": ["sh", "-c", "cd /tmp/work/q4 && P=$(docker port $(docker compose ps -q web) 80/tcp | head -1 | sed \\"s/.*://\\") && [ -n \\"$P\\" ] && [ \\"$P\\" != 8080 ]"]}]', '[{"title": "Compose 파일 보간(interpolation)", "url": "https://docs.docker.com/reference/compose-file/interpolation/"}, {"title": "depends_on", "url": "https://docs.docker.com/reference/compose-file/services/#depends_on"}, {"title": "docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 531 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 531, 5, 'container name is already in use: 이름이 충돌한다', '`/tmp/work/q5` 에서 `docker compose up -d` 를 하면 `Conflict. The container name "/web" is already in use by container ...` 오류가 납니다. `compose.yaml` 이 `container_name: web` 으로 이름을 고정했는데, 예전에 `docker run --name web` 으로 직접 만든 컨테이너가 **같은 이름으로 남아 있기** 때문입니다. 이 옛 컨테이너는 이제 필요 없습니다. 정리하고 compose 로 `web` 을 올려, **compose 가 만든 컨테이너**가 실행 중이게 하세요.', '`docker ps -a` 로 `web` 이 어떻게 만들어졌는지 확인하세요. 필요 없는 컨테이너는 이름으로 지울 수 있습니다. 지운 뒤 compose 로 다시 올립니다.', 'cd /tmp/work/q5
docker ps -a --format ''{{.Names}} {{.Image}}''
docker rm -f web
docker compose up -d
docker compose ps

# 컨테이너 이름은 호스트에서 유일해야 한다. container_name 으로 고정하면 같은 이름의 컨테이너가 있을 때 충돌한다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; rm -rf /tmp/work /tmp/q*.txt; mkdir -p /tmp/work/q5; cat > /tmp/work/q5/compose.yaml <<''EOF''\\nservices:\\n  web:\\n    image: nginx:alpine\\n    container_name: web\\nEOF\\ndocker run -d --name web alpine sleep 3600 >/dev/null; "]', '["sh", "-c", "( [ \\"$(docker inspect -f ''{{index .Config.Labels \\"com.docker.compose.project\\"}}'' web 2>/dev/null)\\" = q5 ] ) && ( [ \\"$(docker inspect -f {{.State.Running}} web 2>/dev/null)\\" = true ] ) && ( docker inspect -f \\"{{.Config.Image}}\\" web | grep -q nginx )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "web 이 compose 가 만든 컨테이너다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{index .Config.Labels \\"com.docker.compose.project\\"}}'' web 2>/dev/null)\\" = q5 ]"]}, {"label": "web 이 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f {{.State.Running}} web 2>/dev/null)\\" = true ]"]}, {"label": "web 이 nginx 이미지다", "cmd": ["sh", "-c", "docker inspect -f \\"{{.Config.Image}}\\" web | grep -q nginx"]}]', '[{"title": "Compose 파일 보간(interpolation)", "url": "https://docs.docker.com/reference/compose-file/interpolation/"}, {"title": "depends_on", "url": "https://docs.docker.com/reference/compose-file/services/#depends_on"}, {"title": "docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 531 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 531, 6, 'depends_on 인데도 db 가 준비되기 전에 접속한다', '`/tmp/work/q6` 의 `app` 은 시작하자마자 `http://db/` 에 접속해 보고 **`CONNECTED` 또는 `FAILED`** 를 로그에 한 번 출력합니다. `db`(nginx)는 일부러 **6초 뒤에야** 응답을 시작하고, `depends_on: [db]` 가 적혀 있는데도 `docker compose logs app` 에는 `FAILED` 가 찍혀 있습니다. 짧은 형태의 `depends_on` 은 db **컨테이너가 시작**되기만 기다리고 **서비스가 준비**됐는지는 보지 않기 때문입니다. `db` 에 이미 있는 `healthcheck` 가 healthy 가 될 때까지 `app` 이 기다리도록 `depends_on` 을 고치세요. 고친 뒤 `docker compose down` 으로 내렸다가 `docker compose up -d` 로 다시 올려 `app` 로그에 `CONNECTED` 가 나오게 하고, 그 로그를 `/tmp/q6.txt` 에 저장하세요.', '긴 형태의 `depends_on` 은 서비스 이름 아래에 `condition:` 키를 둡니다. 어떤 값이 "건강해질 때까지"를 뜻하는지는 Compose 문서의 depends_on 항목에서 찾을 수 있습니다. `app` 은 한 번만 접속을 시도하므로 로그는 다시 올린 뒤에 확인하세요.', 'cd /tmp/work/q6
cat > compose.yaml <<''EOF''
services:
  db:
    image: nginx:alpine
    command: sh -c "sleep 6; exec nginx -g ''daemon off;''"
    healthcheck:
      test: ["CMD", "wget", "-qO-", "http://127.0.0.1/"]
      interval: 1s
      retries: 30
  app:
    image: alpine
    command: sh -c "wget -qO- -T 2 http://db/ >/dev/null && echo CONNECTED || echo FAILED; sleep 3600"
    depends_on:
      db:
        condition: service_healthy
EOF
docker compose down
docker compose up -d
sleep 1
docker compose logs app | tee /tmp/q6.txt

# depends_on 의 기본(service_started)은 시작만 기다린다. condition: service_healthy 는 healthcheck 가 통과할 때까지 기다린다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; rm -rf /tmp/work /tmp/q*.txt; mkdir -p /tmp/work/q6; cat > /tmp/work/q6/compose.yaml <<''EOF''\\nservices:\\n  db:\\n    image: nginx:alpine\\n    command: sh -c \\"sleep 6; exec nginx -g ''daemon off;''\\"\\n    healthcheck:\\n      test: [\\"CMD\\", \\"wget\\", \\"-qO-\\", \\"http://127.0.0.1/\\"]\\n      interval: 1s\\n      retries: 30\\n  app:\\n    image: alpine\\n    command: sh -c \\"wget -qO- -T 2 http://db/ >/dev/null && echo CONNECTED || echo FAILED; sleep 3600\\"\\n    depends_on:\\n      - db\\nEOF\\ncd /tmp/work/q6 && docker compose up -d >/dev/null 2>&1; sleep 3; "]', '["sh", "-c", "( cd /tmp/work/q6 && docker compose config | grep -q \\"condition: service_healthy\\" ) && ( cd /tmp/work/q6 && docker compose logs app 2>/dev/null | grep -q CONNECTED ) && ( grep -q CONNECTED /tmp/q6.txt && ! grep -q FAILED /tmp/q6.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "app 의 depends_on 이 healthy 를 기다린다", "cmd": ["sh", "-c", "cd /tmp/work/q6 && docker compose config | grep -q \\"condition: service_healthy\\""]}, {"label": "app 로그에 CONNECTED 가 있다", "cmd": ["sh", "-c", "cd /tmp/work/q6 && docker compose logs app 2>/dev/null | grep -q CONNECTED"]}, {"label": "저장한 로그에도 CONNECTED 가 있고 FAILED 는 없다", "cmd": ["sh", "-c", "grep -q CONNECTED /tmp/q6.txt && ! grep -q FAILED /tmp/q6.txt"]}]', '[{"title": "Compose 파일 보간(interpolation)", "url": "https://docs.docker.com/reference/compose-file/interpolation/"}, {"title": "depends_on", "url": "https://docs.docker.com/reference/compose-file/services/#depends_on"}, {"title": "docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 531 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 531, 7, 'Found orphan containers: 지운 서비스의 컨테이너가 남는다', '`/tmp/work/q7` 의 `compose.yaml` 에는 원래 `web` 과 `old` 두 서비스가 있었고 이미 올라와 있습니다. 이제 `old` 서비스 정의를 파일에서 **지웠습니다**. 그런데 `docker compose up -d` 를 하면 `Found orphan containers ([q7-old-1]) for this project` 경고만 나오고 **`old` 컨테이너는 계속 실행 중**입니다. 파일에 없는 서비스의 컨테이너(고아)를 함께 정리하면서 올리세요. `web` 은 실행 중이어야 합니다.', '`docker compose up --help` 의 옵션 목록에서 orphan 이라는 단어를 찾아 보세요.', 'cd /tmp/work/q7
docker compose up -d
docker compose up -d --remove-orphans
docker compose ps

# 파일에서 서비스를 지워도 컨테이너는 자동으로 지워지지 않는다. --remove-orphans 가 이 프로젝트의 고아 컨테이너를 정리한다', '["sh", "-c", "docker rm -f $(docker ps -aq) >/dev/null 2>&1; docker network prune -f >/dev/null 2>&1; rm -rf /tmp/work /tmp/q*.txt; mkdir -p /tmp/work/q7; cat > /tmp/work/q7/compose.yaml <<''EOF''\\nservices:\\n  web:\\n    image: nginx:alpine\\n  old:\\n    image: alpine\\n    command: sleep 3600\\nEOF\\ncd /tmp/work/q7 && docker compose up -d >/dev/null 2>&1; printf ''services:\\\\n  web:\\\\n    image: nginx:alpine\\\\n'' > compose.yaml; "]', '["sh", "-c", "( cd /tmp/work/q7 && [ \\"$(docker compose ps -a -q | wc -l)\\" = 1 ] && ! docker ps -a --format \\"{{.Names}}\\" | grep -q old ) && ( cd /tmp/work/q7 && [ \\"$(docker compose ps --status running -q web | wc -l)\\" = 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "old 컨테이너가 없다", "cmd": ["sh", "-c", "cd /tmp/work/q7 && [ \\"$(docker compose ps -a -q | wc -l)\\" = 1 ] && ! docker ps -a --format \\"{{.Names}}\\" | grep -q old"]}, {"label": "web 이 실행 중이다", "cmd": ["sh", "-c", "cd /tmp/work/q7 && [ \\"$(docker compose ps --status running -q web | wc -l)\\" = 1 ]"]}]', '[{"title": "Compose 파일 보간(interpolation)", "url": "https://docs.docker.com/reference/compose-file/interpolation/"}, {"title": "depends_on", "url": "https://docs.docker.com/reference/compose-file/services/#depends_on"}, {"title": "docker compose up", "url": "https://docs.docker.com/reference/cli/docker/compose/up/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 531 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 531, 8, 'depends_on 만 쓰면 무엇이 보장될까', '`app` 서비스가 `depends_on: [db]` 만 적었습니다(조건 없음). `docker compose up -d` 에서 도커가 보장하는 것은 무엇일까요?', '짧게 적은 `depends_on` 의 기본 조건 이름을 떠올려 보세요. "시작"과 "준비"는 다른 말입니다.', NULL, NULL, '[]', 'choice', '["`db` 안의 서버가 접속을 받을 준비가 끝난 뒤 `app` 이 시작된다", "`db` 가 실패하면 `app` 은 자동으로 재시도한다", "`app` 이 `db` 의 데이터 볼륨을 자동으로 공유한다", "`db` 컨테이너가 **시작된 뒤** `app` 이 시작된다 (db 안의 서버가 접속을 받을 준비가 됐는지는 보장하지 않는다)"]', 3, '기본(`service_started`)은 `db` 컨테이너를 먼저 시작하는 순서만 보장합니다. 서버가 실제로 준비됐는지 기다리려면 `db` 에 `healthcheck` 를 두고 `depends_on` 에 `condition: service_healthy` 를 적습니다. 재시도나 볼륨 공유는 `depends_on` 의 역할이 아닙니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 531 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 531, 9, '"port is already allocated" 의 원인', '`docker compose up -d` 가 `Bind for 0.0.0.0:8080 failed: port is already allocated` 로 실패했습니다. 가장 알맞은 원인은 무엇일까요?', '메시지의 `0.0.0.0:8080` 은 컨테이너 안이 아니라 **호스트**의 주소입니다. 호스트의 그 포트를 누가 쓰고 있을지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["컨테이너 안의 nginx 설정 파일 문법이 틀렸다", "이미지를 내려받지 못했다", "호스트의 8080 번 포트를 다른 컨테이너나 프로세스가 이미 쓰고 있다", "compose.yaml 의 들여쓰기가 틀렸다"]', 2, '호스트 포트는 한 번에 한 프로세스만 열 수 있어 `ports` 의 왼쪽(호스트) 번호가 겹치면 이 오류가 납니다. 호스트 쪽 번호를 바꾸거나 쓰고 있는 쪽을 정리합니다. 들여쓰기 오류는 파일을 읽는 단계에서 다른 메시지로, 이미지 문제는 pull 단계에서 납니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 531 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 531, 10, '고아 컨테이너를 함께 정리하며 올리기', '파일에서 지운 서비스의 컨테이너까지 함께 정리하면서 서비스를 백그라운드로 올리는 명령입니다. 빈칸을 채우세요.', '정리할 대상이 "고아(orphan)" 입니다. 옵션 이름은 동사로 시작합니다.', NULL, NULL, '[]', 'fill', '["--remove-orphans", "--force-recreate", "--no-deps", "--abort-on-container-exit"]', NULL, '`--remove-orphans` 는 compose 파일에 더 이상 없는 서비스의 컨테이너를 지웁니다. `--force-recreate` 는 변경이 없어도 컨테이너를 새로 만들고, `--no-deps` 는 의존 서비스를 시작하지 않으며, `--abort-on-container-exit` 는 컨테이너 하나가 끝나면 모두 멈춥니다.', '[0]', 'docker compose up -d {0}', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 531 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 531, 11, 'compose 가 안 올라올 때 점검 순서', '`docker compose up -d` 가 실패했을 때, 파일 자체에서 시작해 실행 결과로 넘어가는 **점검 순서**대로 카드를 놓으세요. 앞 단계가 통과해야 뒤 단계를 볼 의미가 있습니다.', '파일을 읽지 못하면 아무것도 시작되지 않습니다. 앞 단계가 통과해야 뒤 단계의 결과가 의미를 갖는 순서를 찾아 보세요.', NULL, NULL, '[]', 'order', '["`docker compose config -q` 로 파일 문법이 읽히는지 본다", "`docker compose logs <서비스>` 로 서비스 안에서 난 오류를 본다", "`docker compose config` 로 변수가 의도대로 풀렸는지 본다", "`docker compose ps -a` 로 어떤 컨테이너가 안 떴는지 본다"]', NULL, '파일이 읽히지 않으면 아무것도 시작되지 않으므로 문법부터 봅니다. 그다음 변수가 의도대로 풀렸는지 확인하고, 실행했다면 어느 컨테이너가 안 떴는지(`ps -a`), 마지막으로 그 서비스의 로그에서 원인을 봅니다.', '[0, 2, 3, 1]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 531 AND order_index = 11);
